package com.renthub.bookingservice; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; @Entity @Table(name="RH_BOOKING_SERVICES") public class BookingServiceAddon{@Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="bs_seq") @SequenceGenerator(name="bs_seq",sequenceName="RH_BOOKING_SERVICE_SEQ",allocationSize=1) private Long id; private Long bookingId; private Long serviceId; private BigDecimal price; private LocalDateTime createdAt=LocalDateTime.now(); public Long getId(){return id;} public Long getBookingId(){return bookingId;} public void setBookingId(Long v){bookingId=v;} public Long getServiceId(){return serviceId;} public void setServiceId(Long v){serviceId=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;}}
